/* -------------------------------------------------------------------------- */
/* assembly                                                                    */
/* -------------------------------------------------------------------------- */

const file = discovered as DiscoveredFile;

export const DISCOVERED_SOURCES: SourceDefinition[] = file.sources ?? [];

export const ALL_SOURCES: SourceDefinition[] = [
  ...AGGREGATOR_SOURCES,
  ...BOARD_SOURCES,
  ...DISCOVERED_SOURCES,
];

export function enabledSources(opts: { includeBrowser?: boolean } = {}): SourceDefinition[] {
  const { includeBrowser = true } = opts;
  return ALL_SOURCES.filter(
    (s) => s.enabled !== false && (includeBrowser || !s.needsBrowser),
  );
}

export function sourceById(id: string): SourceDefinition | undefined {
  return ALL_SOURCES.find((s) => s.id === id);
}

export function sourceStats() {
  const byKind: Record<string, number> = {};
  const byAdapter: Record<string, number> = {};
  for (const s of ALL_SOURCES) {
    if (s.enabled === false) continue;
    byKind[s.kind] = (byKind[s.kind] ?? 0) + 1;
    byAdapter[s.adapter] = (byAdapter[s.adapter] ?? 0) + 1;
  }
  return {
    total: ALL_SOURCES.filter((s) => s.enabled !== false).length,
    discoveredAt: file.generatedAt,
    employersProbed: file.companies,
    byKind,
    byAdapter,
  };
}

/**
 * Employers the worker found and added by itself (dynamic_sources), merged in
 * at run time - nothing needs a code commit for a new employer to be polled.
 */
export async function dynamicSources(): Promise<SourceDefinition[]> {
  try {
    const { supabaseAdmin } = await import("../db");
    const { data } = await supabaseAdmin().from("dynamic_sources").select("*").eq("enabled", true);
    return (data ?? []).map((r) => ({
      id: String(r.id),
      label: String(r.label),
      company: String(r.company),
      kind: r.kind as SourceDefinition["kind"],
      adapter: String(r.adapter),
      handle: String(r.handle),
      handle2: r.handle2 ?? undefined,
      region: (r.region as SourceDefinition["region"]) ?? "ksa",
      needsBrowser: Boolean(r.needs_browser),
      enabled: true,
    }));
  } catch {
    return [];
  }
}
